// Episode 41 - numerically controlled oscillator: a 32-bit phase accumulator and two 4096-entry look-up tables (cos and -sin, 16 bits), so that mixing with (cos, -sin) moves the wanted frequency down to 0 Hz.
// Output frequency = inc / 2^32 x fs. The tables are generated by tools/ddc_model.py (nco_cos.mem, nco_sin.mem).
module nco (input wire clk, input wire rst, input wire [31:0] inc, output reg signed [15:0] cos_o, output reg signed [15:0] nsin_o);
    reg [31:0] phase;
    reg signed [15:0] ct [0:4095];
    reg signed [15:0] st [0:4095];
    initial begin $readmemh("nco_cos.mem", ct); $readmemh("nco_sin.mem", st); end
    always @(posedge clk)
        if (rst) begin phase <= 32'd0; cos_o <= 16'sd0; nsin_o <= 16'sd0; end
        else begin phase <= phase + inc; cos_o <= ct[phase[31:20]]; nsin_o <= st[phase[31:20]]; end
endmodule
